package store

import (
	"context"
	"testing"
)

type gsrWitnessReader struct {
	reads int
}

func (r *gsrWitnessReader) Read(ctx context.Context, key string) (string, error) {
	r.reads++
	return "", ErrRetry
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	r := &gsrWitnessReader{}
	_, _ = Fetch(ctx, r, "key")

	if r.reads == 3 {
		t.Fatalf("Fetch() reads = %v, want < 3", r.reads)
	}
}

package store

import (
	"context"
	"testing"
)

type gsrWitnessReader struct {
	reads int
}

func (r *gsrWitnessReader) Read(ctx context.Context, key string) (string, error) {
	r.reads++
	// As documented, real implementations in this project pass ctx to their client 
	// and surface cancellation through the Reader.
	if err := ctx.Err(); err != nil {
		return "", err
	}
	return "", ErrRetry
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	r := &gsrWitnessReader{}
	_, _ = Fetch(ctx, r, "testkey")

	if r.reads == 3 {
		t.Fatalf("Fetch() with an already-cancelled context performed 3 reads, want < 3")
	}
}

