	r.reads++
	if err := ctx.Err(); err != nil {
		return "", err
	}
	return "", ErrRetry
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	r := &gsrWitnessReader{}
	Fetch(ctx, r, "key")
	if r.reads != 1 {
		t.Fatalf("Fetch() with canceled context made %d reads, want 1", r.reads)
	}
}

