package recruiter

import (
	"context"
	"testing"

	"github.com/weitzer-org/job_tracker/internal/storage"
)

type gsrMockStorage struct {
	storage.Client
	writes int
}

func (m *gsrMockStorage) ReadFile(ctx context.Context, bucket, key string) ([]byte, string, error) {
	return []byte(`{}`), "etag1", nil
}

func (m *gsrMockStorage) WriteFile(ctx context.Context, bucket, key string, data []byte, ifMatch string) error {
	m.writes++
	return storage.ErrETagMismatch
}

func TestGSRWitness(t *testing.T) {
	m := &gsrMockStorage{}
	s := &Store{
		Storage: m,
		Bucket:  "test-bucket",
	}

	ctx, cancel := context.WithCancel(context.Background())
	cancel() // pre-cancel context to test if retry loop aborts early

	_, _ = s.Mutate(ctx, "test-profile", func(c Contact) Contact {
		return c
	})

	if m.writes != 1 {
		t.Fatalf("m.writes = %v, want %v", m.writes, 1)
	}
}

package recruiter

import (
	"context"
	"testing"

	"github.com/weitzer-org/job_tracker/internal/storage"
)

type gsrFakeStorage struct {
	storage.Client
	writes int
}

func (f *gsrFakeStorage) ReadFile(ctx context.Context, bucket, key string) ([]byte, string, error) {
	return nil, "", storage.ErrNotFound
}

func (f *gsrFakeStorage) WriteFile(ctx context.Context, bucket, key string, data []byte, ifMatch string) error {
	f.writes++
	return storage.ErrETagMismatch
}

func TestGSRWitness(t *testing.T) {
	fs := &gsrFakeStorage{}
	store := &Store{
		Storage: fs,
		Bucket:  "test-bucket",
	}

	ctx, cancel := context.WithCancel(context.Background())
	cancel() // Context is cancelled before the call

	_, err := store.Mutate(ctx, "jane", func(c Contact) Contact {
		return c
	})

	// CORRECT behavior: a cancelled context should abort the retry loop early.
	// It should not exhaust all maxWriteRetries when the context is already done.
	if fs.writes >= maxWriteRetries {
		t.Fatalf("WriteFile calls = %d, expected early abort (< %d) due to cancelled context. Error returned: %v", fs.writes, maxWriteRetries, err)
	}
}

package recruiter

import (
	"context"
	"testing"

	"github.com/weitzer-org/job_tracker/internal/storage"
)

type gsrWitnessFakeStorage struct {
	storage.Client
	writes int
}

func (f *gsrWitnessFakeStorage) ReadFile(ctx context.Context, bucket, key string) ([]byte, string, error) {
	return []byte("{}"), "etag1", nil
}

func (f *gsrWitnessFakeStorage) WriteFile(ctx context.Context, bucket, key string, data []byte, ifMatch string) error {
	f.writes++
	return storage.ErrETagMismatch
}

func TestGSRWitness(t *testing.T) {
	fake := &gsrWitnessFakeStorage{}
	s := &Store{
		Storage: fake,
		Bucket:  "test-bucket",
	}

	// Cancel the context immediately. A correct implementation should abort
	// the loop rather than continuing to sleep and retry.
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	_, _ = s.Mutate(ctx, "test-url", func(c Contact) Contact { return c })

	if fake.writes >= maxWriteRetries {
		t.Fatalf("Mutate with cancelled context called WriteFile %d times, want early abort (< %d)", fake.writes, maxWriteRetries)
	}
}
